package com.example.starter.domain;

/**
 * 原始样本状态。
 */
public enum SpecimenStatus {
    /**
     * 在库：原始样本已入库，可继续分装。
     */
    IN_STOCK
}

package com.example.starter.domain;

/**
 * 分装管（aliquot）状态。
 */
public enum AliquotStatus {
    /**
     * 正常：可被检测申请占用或污染隔离。
     */
    AVAILABLE,
    /**
     * 隔离：发生污染事件，未开始申请被整批取消，已消耗量保留。
     */
    QUARANTINED
}

package com.example.starter.domain;

/**
 * 检测申请（占用记录）状态。
 */
public enum ReservationStatus {
    /**
     * 已预留：aliquot 上有对应体积被占用但尚未消耗。
     */
    RESERVED,
    /**
     * 检测已开始：预留体积转为已消耗，不可取消。
     */
    CONSUMED,
    /**
     * 已取消：仅 RESERVED 可取消或被污染事件联动取消，占用体积已释放。
     */
    CANCELLED
}

package com.example.starter.domain;

/**
 * 可进行保管方交接的实体类型。
 */
public enum EntityType {
    /**
     * 原始样本。
     */
    SPECIMEN,
    /**
     * 分装管。
     */
    ALIQUOT,
    /**
     * 检测申请。
     */
    RESERVATION
}

package com.example.starter.domain;

/**
 * 保管链事件类型。
 */
public enum EventKind {
    /**
     * 原始样本入库并确定首任保管人。
     */
    INTAKE,
    /**
     * 分装管或检测申请创建并确定首任保管人。
     */
    CREATE,
    /**
     * 保管方交接。
     */
    TRANSFER,
    /**
     * 污染隔离，实体保管方转入隔离保管人。
     */
    QUARANTINE
}

package com.example.starter.support;

/**
 * 请求体引用的资源不存在，映射为 HTTP 404。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.support;

/**
 * 状态冲突：版本不符、指纹冲突、超额占用、非法状态迁移或时间倒退，映射为 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.support;

/**
 * 请求参数非法（含体积精度非法），映射为 HTTP 400。
     */
public class BadRequestException extends RuntimeException {

    public BadRequestException(String message) {
        super(message);
    }
}

package com.example.starter.support;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 体积工具：题面体积单位为微升（µL），最多三位小数。
 *
 * <p>内部统一用纳升（nL）长整数存储，{@code 1 nL = 0.001 µL}，
 * 全部分装、占用、守恒计算只做整数运算，避免二进制浮点误差。</p>
 */
public final class Volume {

    /**
     * 1 微升对应的内部单位数量（千分之一微升即 1 纳升）。
     */
    public static final long SCALE = 1000L;

    private Volume() {
    }

    /**
     * 将最多三位小数的微升字符串解析为纳升整数。
     *
     * @param text       微升体积字符串
     * @param fieldName  字段名，用于错误提示
     * @return 纳升体积，恒为正
     * @throws BadRequestException 格式错误、超过三位小数或非正数
     */
    public static long parsePositiveNl(String text, String fieldName) {
        if (text == null || text.isBlank()) {
            throw new BadRequestException(fieldName + " 不能为空");
        }
        final BigDecimal value;
        try {
            value = new BigDecimal(text.trim()).stripTrailingZeros();
        } catch (NumberFormatException ex) {
            throw new BadRequestException(fieldName + " 不是合法体积: " + text);
        }
        if (value.signum() <= 0) {
            throw new BadRequestException(fieldName + " 必须为正数: " + text);
        }
        if (value.scale() > 3) {
            throw new BadRequestException(fieldName + " 最多允许三位小数: " + text);
        }
        return value.setScale(3, RoundingMode.UNNECESSARY)
                .multiply(BigDecimal.valueOf(SCALE))
                .longValueExact();
    }

    /**
     * 将纳升整数格式化为三位小数微升字符串（去除尾随零）。
     */
    public static String formatUl(long nl) {
        return BigDecimal.valueOf(nl, 3).stripTrailingZeros().toPlainString();
    }
}

package com.example.starter.support;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;

import org.springframework.stereotype.Component;

/**
 * 统一时间来源，生产环境使用 Asia/Shanghai 系统时钟；
 * 测试可替换为固定或可控时钟，以便验证时间不倒退规则。
 */
@Component
public class LabClock {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private volatile Clock clock = Clock.system(ZONE);

    /**
     * 当前时间。
     */
    public Instant now() {
        return Instant.now(clock);
    }

    /**
     * 替换底层时钟，仅供测试使用。
     */
    public void setClock(Clock clock) {
        this.clock = clock;
    }
}

