                row.custodian(),
                row.version(),
                row.createdAt(),
                row.updatedAt());
    }

    public ReservationView toReservationView(ReservationRow row) {
        return new ReservationView(
                row.requestId(),
                row.aliquotId(),
                row.projectCode(),
                Volume.formatUl(row.volumeNl()),
                row.status().name(),
                row.custodian(),
                row.version(),
                parseResult(row.resultPayload()),
                row.resultAt(),
                row.createdAt(),
                row.updatedAt());
    }

    public CustodyEventView toEventView(CustodyEventRow row) {
        return new CustodyEventView(
                row.entityType().name(),
                row.entityId(),
                row.eventKind().name(),
                row.fromCustodian(),
                row.toCustodian(),
                row.versionBefore(),
                row.versionAfter(),
                row.occurredAt(),
                row.note());
    }

    private Object parseResult(String json) {
        if (json == null) {
            return null;
        }
        try {
            return objectMapper.readValue(json, Object.class);
        } catch (IOException ex) {
            return Map.of("raw", json);
        }
    }
}

